INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Latenz nur bei Multicast ein Problem?', 2, '[{"text": "Nein", "correct": true, "because": "Betrifft alle Kommunikationsarten"}, {"text": "Ja", "correct": false, "because": "Nicht Multicast-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool misst Latenz im Netzwerk?', 3, '[{"text": "ping", "correct": true, "because": "Zeigt Rundlaufzeit"}, {"text": "ipconfig", "correct": false, "because": "Nur Konfiguration"}, {"text": "dhclient", "correct": false, "because": "Adresszuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen Latenz?', 5, '[{"text": "Netzwerküberlastung", "correct": true, "because": "Verursacht Verzögerung"}, {"text": "Hop-Anzahl", "correct": true, "because": "Mehr Router, mehr Zeit"}, {"text": "IP-Adresse", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "DNS-Name", "correct": false, "because": "Nur Auflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast kann Latenz erhöhen. b) Latenz ist immer messbar.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Multicast kann überlasten, Latenz ist quantifizierbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Latenzmessung?', 4, '[{"text": "Rundlaufzeit", "correct": false, "because": "Kern der Messung"}, {"text": "Paketverlust", "correct": false, "because": "Zeigt Zuverlässigkeit"}, {"text": "Webserver-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast immer Latenz erhöht?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Netzwerk"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Messung zeigt Latenzprobleme?', 3, '[{"text": "Ping-Zeit", "correct": true, "because": "Misst Verzögerung"}, {"text": "DHCP-Lease", "correct": false, "because": "Adresszuweisung"}, {"text": "Router-Status", "correct": false, "because": "Nur Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Effekte hat Multicast auf Latenz?', 5, '[{"text": "Mehr Antworten", "correct": true, "because": "Gruppe antwortet"}, {"text": "Netzlast erhöht", "correct": true, "because": "Viele Geräte aktiv"}, {"text": "Datenkompression", "correct": false, "because": "Nicht Multicast"}, {"text": "IP-Zuweisung", "correct": false, "because": "SLAAC/DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Latenz ist bei Multicast höher. b) Ping misst keine Latenz. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ping misst Latenz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Latenzmessung?', 4, '[{"text": "Ping", "correct": false, "because": "Misst Rundlaufzeit"}, {"text": "Zieladresse", "correct": false, "because": "Definiert Test"}, {"text": "Web-UI", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verursacht Multicast immer Latenz?', 2, '[{"text": "Nein", "correct": true, "because": "Kontextabhängig"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor zeigt Latenzprobleme bei Multicast?', 4, '[{"text": "Hohe Antwortzeit", "correct": true, "because": "Viele Geräte antworten"}, {"text": "IP-Konflikte", "correct": false, "because": "SLAAC-spezifisch"}, {"text": "DNS-Ausfall", "correct": false, "because": "Namensauflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Latenz nur bei Unicast auftritt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Typen betroffen"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Latenzmessung?', 3, '[{"text": "Ping-Ergebnisse", "correct": true, "because": "Zeigt Verzögerung"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "DNS-Server", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast kann Latenz verschlechtern. b) Latenz ist nur Hardware-bedingt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerkfaktoren zählen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Latenzmessung?', 5, '[{"text": "Engpass-Erkennung", "correct": true, "because": "Zeigt Verzögerungen"}, {"text": "Leistungsanalyse", "correct": true, "because": "Netzwerkzustand"}, {"text": "Adresszuweisung", "correct": false, "because": "DHCP-Aufgabe"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Latenzproblemen unwichtig?', 3, '[{"text": "Rundlaufzeit", "correct": false, "because": "Kern der Messung"}, {"text": "Netzwerküberlastung", "correct": false, "because": "Hauptursache"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Multicast die Latenz immer?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Nutzung"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob traceroute Latenz misst?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigt Zeit pro Hop"}, {"text": "Nein", "correct": false, "because": "Teil der Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Antwort zeigt Latenzprobleme bei Multicast?', 4, '[{"text": "Hohe Ping-Zeit", "correct": true, "because": "Verzögerung sichtbar"}, {"text": "Echo Reply fehlt", "correct": false, "because": "Erreichbarkeit"}, {"text": "Router Advertisement", "correct": false, "because": "SLAAC-spezifisch"}]');
